  555,
  'S',
  '2301012',
  'Servicio de acceso Zonas Wifi',
  'Se refiere a la contratación de la zona wifi, que hace el Fontic con el operador en áreas urbanas (centros poblados) con redes terrestres. Implica las labores que tienen que ver con el montaje y puesta en servicio de la zona wifi, el cual es medido a través de la cantidad de usuarios (dispositivos a la zona), y la asistencia personalizada y virtual a los mismos. ',
