INSERT INTO SPD_PRODUCT_CATALOG (ID, IS_ACTIVE, CODE, NAME, DESCRIPTION, UNITS_NAME, PARENT_ID, IS_PRINCIPAL, IS_NATIONAL, IS_TERRITORIAL, IS_LEAF, CREATED_AT, UPDATED_AT) VALUES (
  556,
  'S',
  '2301024',
  'Servicio de acceso y uso de Tecnologías de la Información y las Comunicaciones',
  'Se prestan Servicio a la comunidad, tales como: i) acceso a Internet, ii) uso de aula de capacitaciones enfocada en informática e Internet  y iii) Entretenimiento a través de consolas de video juegos. Adicionalmente, se cuenta con un área de competencias especializadas, para la formación de estudiantes en competencias en Tecnologías de la Información, tales como animación 2D, 3D, emprendimiento Digital, producción de audio y video digital para socializar a través de la web, diseño de efectos especiales, desarrollo web para móviles y videojuegos, entre otros.  Se prestan Servicio telecomunicaciones básicos para las comunidades donde este acceso es limitado o nulo.',
  NULL,
  120,
  NULL,
  NULL,
  NULL,
  'N',
  TIMESTAMP '2026-11-12 13:59:23.352514 +00:00',
  TIMESTAMP '2026-11-12 13:59:23.352514 +00:00');
INSERT INTO SPD_PRODUCT_CATALOG (ID, IS_ACTIVE, CODE, NAME, DESCRIPTION, UNITS_NAME, PARENT_ID, IS_PRINCIPAL, IS_NATIONAL, IS_TERRITORIAL, IS_LEAF, CREATED_AT, UPDATED_AT) VALUES (
  557,
  'S',
  '2301021',
  'Servicio de telecomunicaciones de voz para las entidades del Sistema nacional de Riesgos y Desastres',
  'El servicio hace referencia al alistamiento necesario para la atención de situaciones de riesgo y desastres, mediante una Red de Radios en bandas HF y VHF conformada por la infraestructura actualmente existente en la Unidad Nacional para la Gestión del Riesgo de Desastres - UNGRD, en los Consejos Departamentales de Gestión del Riesgo de Desastres - CDGRD  y en los Consejos Municipales de Gestión del Riesgo de Desastres – CMGRD, con interoperabilidad con las redes de telecomunicaciones que son de propiedad de las entidades que hacen parte del SNGRD y que intervienen directamente en las diferentes fases de la gestión del riesgo de desastres.',
  NULL,
  120,
  NULL,
  NULL,
  NULL,
  'N',
  TIMESTAMP '2026-11-12 13:59:23.352514 +00:00',
  TIMESTAMP '2026-11-12 13:59:23.352514 +00:00');
