  '2401054',
  'Servicio de administración vial en vías primarias',
  'Incluye acciones consistentes en la administración permanente, durante un tiempo determinado, de un sector ó sectores de carretera, que se ejecuta mediante gestiones, acciones y actividades técnicas y administrativas tendientes a conservar el sector de la carretera nacional, que buscan  realizar labores de dirección del mantenimiento rutinario, vigilancia, monitoreo, evaluación y diagnostico continuos del estado de las vías, para garantizar la transitabilidad a los usuarios en condiciones aceptables y seguras, planteando acciones preventivas y correctivas, logrando una reducción en los costos de mantenimiento y conservación de éstas. Igualmente incluye actividades tendientes a gestionar el suministro de mezcla y/o afirmado para mejorar la transitabilidad de la vía, con mano de obra de Microempresas contratada para realizar el Mantenimiento rutinario, ofreciendo seguridad y confort a los usuarios.',
