  'Servicios a la navegación aérea a baja altura está relacionado con los diferentes procedimientos de control, vigilancia, registro, que facilitan el tránsito aéreo de las aeronaves no tripuladas durante su operación en el espacio aéreo colombiano, en el cual se comparten datos necesarios entre la autoridad aeronáutica , empresas aéreas y las tripulaciones con el fin de que el ejercicio de la aviación en Colombia se desarrollen bajo principios de seguridad operacional, eficiencia y oportunidad. ',
