  'Sistemas de contención vehicular',
  'Los sistemas de contención vehicular son dispositivos que se instalan en las zonas laterales de una carretera o en las fajas de separación de calzadas en sentido contrario. Su finalidad es retener y redireccionar los vehículos que se salen fuera de control de la vía, de manera que se limiten los daños y lesiones, tanto para los ocupantes como para los otros usuarios de la carretera y personas u objetos situados en las cercanías, tales como viviendas, escuelas, ciclovías, personas y objetos en zonas de obras.',
