  '2701028',
  'Salas de audiencia restauradas y dotadas',
  'Se refiere a las obras tendientes a recuperar y adaptar Salas de Audiencia, o un edificio de Salas de Audiencia, o parte de éste, con el fin de conservar y revelar sus valores estéticos, históricos y simbólicos. Se fundamenta en el respeto por su integridad y autenticidad; incluyendo las liberaciones o demoliciones parciales de agregados de los bienes de interés culturas, aprobadas por la autoridad competente. Salas de audiencia: Espacio destinado  para el desarrollo de audiencias de juzgamiento, conformadas por el estrado (compuesto de un puesto para Juez y uno para el secretario); el área central (las partes, el testigo, Fiscalía, Defensoría, Procuraduría, Ministerio Público); y,  un área para el  público.',
