  1228,
  'S',
  '2701008',
  'Servicio de información de grabación de audiencias',
  'Este es un sistema que permite realizar la grabación de audiencias presenciales, entre otras funcionaliadades tales como: indexación o catalogación por las partes del proceso, consulta por dicha indexación, permite incluir acta, obtener copias en CD o DVD, incluir documentación probatoria adicional como parte integrante de la grabación, salvaguardar la información en forma automática en sitios centralizados, a través de este servicio se pone a disposición de los jueces información necesaria para la toma de decisiones dentro de los procesos judiciales que se adelantan, así como a disposición de los usuarios de la justicia.',
  NULL,
  139,
  NULL,
  NULL,
  NULL,
  'N',
