  'Se refiere a la obra nueva para edificación de Palacios de Justicia en terrenos no construidos o cuya área esté libre por autorización o demolición total.  A través de este producto se harán más accesibles los servicios de justicia hacia el ciudadano y más eficiente la labor de los administradores de justicia. Palacio de Justicia: Edificio destinado para el funcionamiento conjunto de despachos judiciales, tribunales y altas cortes.',
