  'Se refiere a la obra nueva, para adelantar obras de edificación de  edificios de Salas de Audiencias o Salas de Audiencia, en terrenos no construidos o cuya área esté libre por autorización o demolición total. Salas de audiencia:Espacio destinado  para el desarrollo de audiencias de juzgamiento, conformadas por el estrado (compuesto de un puesto para Juez y uno para el secretario); el área central (las partes, el testigo, Fiscalía, Defensoría, Procuraduría, Ministerio Público); y,  un área para el  público. ',
