  1238,
  'S',
  '2701050',
  'Servicio de conformación de registros de elegibles de la rama judicial',
  'Incluye la estructuración y diseño de la convocatoria al concurso de méritos para proveer los cargos de carrera judicial de la rama judicial, esto incluye actividades de diseño, aplicación y calificación de pruebas, entrega de resultados, estructuración del registro de elegibles y envío de listas en firme. De conformidad con la ley estatutaria de justicia - ley 270 de 1996 el concurso de méritos deberá adelantarse cada dos años por el Consejo Superior de la Judicatura.',
  NULL,
