  'Incluye los documentos y estudios especiales para construir conocimiento en aspectos que incluye en la gestión judicial, el contexto juridico del país, adaptación a los cambios normativos, análisis de datos para la toma de decisiones y generación de herramientas para la producción y gestión de la información que contribuya a la toma de decisiones y modernización de la Rama Judicial.',
